CREATE TABLE stocks (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, provider_symbol TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlists (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE watchlist_stocks (watchlist_id INTEGER NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, stock_id INTEGER NOT NULL REFERENCES stocks(id) ON DELETE CASCADE, PRIMARY KEY (watchlist_id, stock_id));
CREATE TABLE daily_bars (stock_id INTEGER NOT NULL REFERENCES stocks(id) ON DELETE CASCADE, trading_date TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume INTEGER NOT NULL, PRIMARY KEY (stock_id, trading_date));
CREATE TABLE hourly_bars (stock_id INTEGER NOT NULL REFERENCES stocks(id) ON DELETE CASCADE, trading_time TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume INTEGER NOT NULL, PRIMARY KEY (stock_id, trading_time));
CREATE TABLE alerts (id INTEGER PRIMARY KEY, stock_id INTEGER NOT NULL REFERENCES stocks(id) ON DELETE CASCADE, direction TEXT NOT NULL CHECK(direction IN ('above', 'below')), target REAL NOT NULL CHECK(target > 0), armed INTEGER NOT NULL DEFAULT 1 CHECK(armed IN (0, 1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alert_deliveries (id INTEGER PRIMARY KEY, alert_id INTEGER NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, delivered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, price REAL NOT NULL);
